window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f148e3e51df894e7"]={"versions": [{"id": "FIG-f148e3e51df894e7", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Aktivitätsdiagramm der AUTOSAR-Methodik (Methodology Overview). Das Diagramm visualisiert die übergeordneten Phasen und Transformationsschritte des Entwicklungs-Workflows in drei horizontal gestaffelten Domänen-Ebenen: System, ECU und Component. Es ordnet Entwicklungsaktivitäten (gelbe Pfeilsymbole) und Artefakte bzw. Schnittstellenbeschreibungen (blaue Dokumentensymbole sowie Netzwerksymbole) den jeweiligen Ebenen zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Strukturbereiche mit folgenden Artefakten und Aktivitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>System</strong>:</li>\n<li>Artefakt: <code>System Configuration Input : System</code> (<code>.XML</code>)</li>\n<li>Aktivität: <code>Configure System</code></li>\n<li>Artefakt: <code>System Configuration Description :System</code> (<code>.XML</code>)</li>\n<li><strong>Übergreifende Aktivität</strong>:</li>\n<li><code>Extract ECU-Specific Information</code> (verbindet System- und ECU-Ebene)</li>\n<li><strong>ECU</strong>:</li>\n<li>Artefakt: <code>ECU related templates</code> (<code>.XML</code>)</li>\n<li>Artefakt: <code>ECU Extract of System Configuration :System</code> (<code>.XML</code>)</li>\n<li>Aktivität: <code>Configure ECU</code></li>\n<li>Artefakt: <code>ECU Configuration Description</code> (<code>.XML</code>)</li>\n<li>Aktivität: <code>Generate Executable</code></li>\n<li>Artefakt: <code>ECU Executable</code> (<code>.exe</code>)</li>\n<li><strong>Component</strong>:</li>\n<li>Artefakt: <code>Component related templates</code> (symbolisiert durch vernetzte Komponentenboxen)</li>\n<li>Aktivität: <code>Implement Component</code></li>\n<li>Artefakt: <code>Implemented Component</code> (Code-Artefakt ohne Dateiendungsaufdruck)</li>\n</ul>\n<p class=\"fig-p\">Eingangsbeziehungen und Rückführungen:</p>\n<ul class=\"fig-list\">\n<li>Gestrichelte Pfeile führen von <code>System Configuration Input : System</code> zu <code>ECU related templates</code> und <code>Component related templates</code>.</li>\n<li>Gestrichelte Rückführungs-/Feedback-Pfeile verlaufen von <code>ECU Extract of System Configuration :System</code> zu <code>ECU related templates</code> sowie von <code>ECU Configuration Description</code> zu <code>ECU Extract of System Configuration :System</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf folgt einem modellbasierten Transformationsprozess:</p>\n<ol class=\"fig-list\">\n<li>Auf Systemebene wird aus dem initialen <code>System Configuration Input : System</code> über den Schritt <code>Configure System</code> die <code>System Configuration Description :System</code> erzeugt.</li>\n<li>Der Schritt <code>Extract ECU-Specific Information</code> leitet aus der System Configuration Description das <code>ECU Extract of System Configuration :System</code> für ein spezifisches Steuergerät ab.</li>\n<li>Parallel dazu werden initiale Vorlagen aus dem System Configuration Input für die Komponentenentwicklung (<code>Component related templates</code>) und Steuergeräte-Templates (<code>ECU related templates</code>) bereitgestellt.</li>\n<li>Auf Komponentenebene führt <code>Implement Component</code> auf Basis der Templates zum <code>Implemented Component</code>.</li>\n<li>Auf ECU-Ebene wird mittels <code>Configure ECU</code> unter Hinzunahme des ECU-Extrakts und der ECU-Templates die <code>ECU Configuration Description</code> erarbeitet.</li>\n<li>Die Aktivität <code>Generate Executable</code> führt die <code>ECU Configuration Description</code> und die <code>Implemented Component</code> zusammen und erzeugt das finale <code>ECU Executable</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert den normativen Top-Level-Ablauf der AUTOSAR-Entwicklungsmethodik für das Zusammenspiel von VFB, RTE, BSW und Applikations-SWCs.</p>\n<p class=\"fig-p\">Entwickler müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Standardisierte XML-Austauschformate (AUTOSAR XML, ARXML) bilden die Grundlage für System Configuration, ECU Extract und ECU Configuration Description.</li>\n<li>Die Trennung von Komponentenimplementierung und ECU-Integration ermöglicht parallele Entwicklungsstränge zwischen Zulieferern und Fahrzeugherstellern.</li>\n<li>Zur Erzeugung des lauffähigen Binärabbilds (<code>ECU Executable</code>) sind sowohl die komponentenseitigen Implementierungsartefakte als auch die vollständige ECU-Konfigurationsbeschreibung (BSW- und RTE-Konfiguration) erforderlich.</li>\n</ul>"}, {"id": "FIG-f5f0a3c7f9c36c6f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Aktivitätsdiagramm der AUTOSAR-Methodik (Methodology Overview). Das Diagramm visualisiert die übergeordneten Phasen und Transformationsschritte des Entwicklungs-Workflows in drei horizontal gestaffelten Domänen-Ebenen: System, ECU und Component. Es ordnet Entwicklungsaktivitäten (gelbe Pfeilsymbole) und Artefakte bzw. Schnittstellenbeschreibungen (blaue Dokumentensymbole sowie Netzwerksymbole) den jeweiligen Ebenen zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Strukturbereiche mit folgenden Artefakten und Aktivitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>System</strong>:</li>\n<li>Artefakt: <code>System Configuration Input : System</code> (<code>.XML</code>)</li>\n<li>Aktivität: <code>Configure System</code></li>\n<li>Artefakt: <code>System Configuration Description :System</code> (<code>.XML</code>)</li>\n<li><strong>Übergreifende Aktivität</strong>:</li>\n<li><code>Extract ECU-Specific Information</code> (verbindet System- und ECU-Ebene)</li>\n<li><strong>ECU</strong>:</li>\n<li>Artefakt: <code>ECU related templates</code> (<code>.XML</code>)</li>\n<li>Artefakt: <code>ECU Extract of System Configuration :System</code> (<code>.XML</code>)</li>\n<li>Aktivität: <code>Configure ECU</code></li>\n<li>Artefakt: <code>ECU Configuration Description</code> (<code>.XML</code>)</li>\n<li>Aktivität: <code>Generate Executable</code></li>\n<li>Artefakt: <code>ECU Executable</code> (<code>.exe</code>)</li>\n<li><strong>Component</strong>:</li>\n<li>Artefakt: <code>Component related templates</code> (symbolisiert durch vernetzte Komponentenboxen)</li>\n<li>Aktivität: <code>Implement Component</code></li>\n<li>Artefakt: <code>Implemented Component</code> (Code-Artefakt ohne Dateiendungsaufdruck)</li>\n</ul>\n<p class=\"fig-p\">Eingangsbeziehungen und Rückführungen:</p>\n<ul class=\"fig-list\">\n<li>Gestrichelte Pfeile führen von <code>System Configuration Input : System</code> zu <code>ECU related templates</code> und <code>Component related templates</code>.</li>\n<li>Gestrichelte Rückführungs-/Feedback-Pfeile verlaufen von <code>ECU Extract of System Configuration :System</code> zu <code>ECU related templates</code> sowie von <code>ECU Configuration Description</code> zu <code>ECU Extract of System Configuration :System</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf folgt einem modellbasierten Transformationsprozess:</p>\n<ol class=\"fig-list\">\n<li>Auf Systemebene wird aus dem initialen <code>System Configuration Input : System</code> über den Schritt <code>Configure System</code> die <code>System Configuration Description :System</code> erzeugt.</li>\n<li>Der Schritt <code>Extract ECU-Specific Information</code> leitet aus der System Configuration Description das <code>ECU Extract of System Configuration :System</code> für ein spezifisches Steuergerät ab.</li>\n<li>Parallel dazu werden initiale Vorlagen aus dem System Configuration Input für die Komponentenentwicklung (<code>Component related templates</code>) und Steuergeräte-Templates (<code>ECU related templates</code>) bereitgestellt.</li>\n<li>Auf Komponentenebene führt <code>Implement Component</code> auf Basis der Templates zum <code>Implemented Component</code>.</li>\n<li>Auf ECU-Ebene wird mittels <code>Configure ECU</code> unter Hinzunahme des ECU-Extrakts und der ECU-Templates die <code>ECU Configuration Description</code> erarbeitet.</li>\n<li>Die Aktivität <code>Generate Executable</code> führt die <code>ECU Configuration Description</code> und die <code>Implemented Component</code> zusammen und erzeugt das finale <code>ECU Executable</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert den normativen Top-Level-Ablauf der AUTOSAR-Entwicklungsmethodik für das Zusammenspiel von VFB, RTE, BSW und Applikations-SWCs.</p>\n<p class=\"fig-p\">Entwickler müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Standardisierte XML-Austauschformate (AUTOSAR XML, ARXML) bilden die Grundlage für System Configuration, ECU Extract und ECU Configuration Description.</li>\n<li>Die Trennung von Komponentenimplementierung und ECU-Integration ermöglicht parallele Entwicklungsstränge zwischen Zulieferern und Fahrzeugherstellern.</li>\n<li>Zur Erzeugung des lauffähigen Binärabbilds (<code>ECU Executable</code>) sind sowohl die komponentenseitigen Implementierungsartefakte als auch die vollständige ECU-Konfigurationsbeschreibung (BSW- und RTE-Konfiguration) erforderlich.</li>\n</ul>"}], "trans": [{"from": "FIG-f148e3e51df894e7", "to": "FIG-f5f0a3c7f9c36c6f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
